"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { ReceiptText } from "lucide-react";

export default function Home() {
  const router = useRouter();

  // 🔹 State για επιλεγμένα βιβλία
  type SelectedBooks = {
    calc: boolean;
    management: boolean;
    computers: boolean;
    marketing: boolean;
    accounting: boolean;
  };
  type BookKey = keyof SelectedBooks;
  
  const [selected, setSelected] = useState<SelectedBooks>({
    calc: false,
    management: false,
    computers: false,
    marketing: false,
    accounting: false
  });

  // 🔹 Totals
  const [totalAmount, setTotalAmount] = useState(0);
  const [totalBooks, setTotalBooks] = useState(0);
  const [totalStores, setTotalStores] = useState(0);

  // 🔹 Τιμές βιβλίων
  const prices: Record<BookKey, number> = {
    calc: 2,
    management: 0,
    computers: 1.5,
    marketing: 0,
    accounting: 1.5
  };

  // 🔹 Εκδότες (για unique stores)
  const stores: Record<BookKey, string> = {
    calc: "Broken Hill",
    management: "Broken Hill",
    computers: "Βιβλιοδιανομή ΟΠΑ",
    marketing: "Σταμούλη",
    accounting: "ΜΠΕΝΟΥ"
  };

  // 🔹 Handler checkbox
  const handleSelect = (key: BookKey) => {
    setSelected(prev => {
      const updated = { ...prev, [key]: !prev[key] } as SelectedBooks;

      const selectedKeys = (Object.keys(updated) as BookKey[]).filter(k => updated[k]);

      // Υπολογισμός totals
      setTotalBooks(selectedKeys.length);
      setTotalAmount(selectedKeys.reduce((sum, k) => sum + prices[k], 0));
      setTotalStores(new Set(selectedKeys.map(k => stores[k])).size);

      return updated;
    });
  };

  // 🔹 Αποστολή στο backend
  const sendToBackend = async () => {
    try {
      const payload = { selected, totalAmount, totalBooks, totalStores };

      const response = await fetch("http://localhost:8080/api/books/selection", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      const data = await response.text();
      console.log("Backend response:", data);
    } catch (err) {
      console.error("Error sending data:", err);
    }
  };

  // 🔹 Συνάρτηση για κουμπί Continue
  const handleContinue = async () => {
    await sendToBackend();       // Στέλνουμε τα δεδομένα
    router.push("/orderbooks");  // Μετά μεταβαίνουμε στη σελίδα orderbooks
  };

  return (
    <div className="container bg-white rounded-4xl mx-auto px-4 py-6">
      {/* Header */}
      <div className="flex justify-center lg:justify-start items-start px-16 pt-7 pb-15">
        <h1 className="text-4xl font-bold text-primary-dark">
          Επίλεξε τα συγγράμματα που θέλεις να σου αποσταλούν
        </h1>
      </div>

      <div className="flex gap-10 px-16">
        {/* Αριστερή στήλη: Cards */}
        <div className="flex-1 grid auto-rows-auto gap-y-5 pb-20">
          {/* ... τα cards σου (όπως είναι ήδη) */}
        </div>

        {/* Summary */}
        <div className="w-full sm:w-3/4 md:w-1/2 lg:w-1/3 xl:w-1/4 sticky top-6 self-start border-3 border-secondary-border shadow-sm bg-white-light px-4 py-5 sm:px-6 sm:py-6 rounded-3xl mx-auto">
          <h3 className="flex items-center gap-2 text-lg font-bold text-primary-dark mb-6">
            <ReceiptText className="w-5 h-5 text-primary-dark" />
            Summary
          </h3>

          <div className="flex justify-between items-center text-gray-600 mb-4">
            <p>Total amount</p>
            <span className="text-primary-dark font-semibold">{totalAmount} €</span>
          </div>
          <div className="flex justify-between items-center text-gray-600 mb-4">
            <p>Books selected</p>
            <span className="text-primary-dark font-semibold">{totalBooks}</span>
          </div>
          <div className="flex justify-between items-center text-gray-600 mb-6">
            <p>Stores</p>
            <span className="text-primary-dark font-semibold">{totalStores}</span>
          </div>

          {/* 🔹 Κουμπί Continue */}
          <div className="flex justify-center mt-6">
            <button
              onClick={handleContinue}
              className="bg-primary-dark text-white py-2 px-10 rounded-3xl font-semibold hover:bg-primary-dark/90"
            >
              Continue
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

